import { computed, ref, watch } from 'vue'

import type { LGraphNode } from '@/lib/comfyApp'
import { computeFit } from '@/composables/widgets/useVideoViewport'
import { useStageStore, type StageState } from '@/stores/stageStore'
import { uploadCanvas } from '@/utils/uploadCanvas'
import { getWidget, readWidgetNum, writeWidget } from '@/utils/widget'

const SCHEDULE_DELAY_MS = 250
const MIN_GRID = 1
const MAX_GRID = 10
const MIN_BORDER = 0

export const MIN_DIVIDER_PX = 2

export interface DisplayedImage {
  w: number
  h: number
  ox: number
  oy: number
  scale: number
}

export function displayedImageRect(
  natW: number,
  natH: number,
  contW: number,
  contH: number,
): DisplayedImage | null {
  if (natW <= 0 || natH <= 0 || contW <= 0 || contH <= 0) return null
  const fit = computeFit(contW, contH, natW, natH)
  return {
    w: natW * fit.scale,
    h: natH * fit.scale,
    ox: fit.offX,
    oy: fit.offY,
    scale: fit.scale,
  }
}

export function dividerCenters(
  n: number,
  natSize: number,
  border: number,
  outer: boolean,
): number[] {
  const o = outer ? 1 : 0
  const cell = (natSize - (n - 1 + 2 * o) * border) / n
  const centers: number[] = []
  if (o && border > 0) centers.push(border / 2)
  for (let k = 1; k < n; k++) centers.push(o * border + k * cell + (k - 0.5) * border)
  if (o && border > 0) centers.push(natSize - border / 2)
  return centers
}

export function dividerBands(
  axis: 'v' | 'h',
  d: DisplayedImage,
  natSize: number,
  count: number,
  border: number,
  outer: boolean,
): Record<string, string>[] {
  const b = Math.max(0, border)
  const thick = Math.max(MIN_DIVIDER_PX, b * d.scale)
  return dividerCenters(count, natSize, b, outer).map((centerNat) =>
    axis === 'v'
      ? {
          left: `${d.ox + centerNat * d.scale - thick / 2}px`,
          top: `${d.oy}px`,
          width: `${thick}px`,
          height: `${d.h}px`,
        }
      : {
          left: `${d.ox}px`,
          top: `${d.oy + centerNat * d.scale - thick / 2}px`,
          width: `${d.w}px`,
          height: `${thick}px`,
        })
}

export function useGridSplit(node: LGraphNode, state: StageState) {
  const store = useStageStore()

  const sourceImageUrl = computed<string | null>(() => {
    const inp = state.inputs.find(i => i.slot === 'image')
    return inp && inp.source === 'upstream' && inp.content ? inp.content : null
  })

  const rows = ref<number>(readWidgetNum(node, 'rows', 2))
  const cols = ref<number>(readWidgetNum(node, 'cols', 2))
  const border = ref<number>(Math.max(MIN_BORDER, readWidgetNum(node, 'border', 0)))
  const outerBorder = ref<boolean>(!!getWidget(node, 'outer_border')?.value)

  function setGrid(r: number, c: number) {
    rows.value = Math.max(MIN_GRID, Math.min(MAX_GRID, r))
    cols.value = Math.max(MIN_GRID, Math.min(MAX_GRID, c))
  }

  function setBorder(v: number) {
    border.value = Math.max(MIN_BORDER, Math.round(Number.isFinite(v) ? v : 0))
  }

  function setOuterBorder(v: boolean) {
    outerBorder.value = !!v
  }

  function wireWidget(name: string, apply: (v: number) => void) {
    const w = getWidget(node, name)
    if (!w) return
    const orig = w.callback
    w.callback = (v: unknown) => { orig?.call(w, v); apply(Number(v)) }
  }
  wireWidget('rows', (v) => { if (v !== rows.value) rows.value = v })
  wireWidget('cols', (v) => { if (v !== cols.value) cols.value = v })
  wireWidget('border', (v) => { if (v !== border.value) border.value = Math.max(MIN_BORDER, v) })

  {
    const w = getWidget(node, 'outer_border')
    if (w) {
      const orig = w.callback
      w.callback = (v: unknown) => { orig?.call(w, v); outerBorder.value = !!v }
    }
  }

  if (node) {
    const orig = node.onConfigure
    node.onConfigure = function (info: any) {
      orig?.call(this, info)
      const r = readWidgetNum(node, 'rows', rows.value)
      const c = readWidgetNum(node, 'cols', cols.value)
      const b = readWidgetNum(node, 'border', border.value)
      const o = !!getWidget(node, 'outer_border')?.value
      if (r !== rows.value) rows.value = r
      if (c !== cols.value) cols.value = c
      if (b !== border.value) border.value = Math.max(MIN_BORDER, b)
      if (o !== outerBorder.value) outerBorder.value = o
    }
  }

  const splitting = ref(false)
  let timer: number | null = null
  let seq = 0
  let cachedImg: HTMLImageElement | null = null
  let cachedUrl: string | null = null

  function getSourceImage(url: string): Promise<HTMLImageElement> {
    if (cachedImg && cachedUrl === url && cachedImg.complete) {
      return Promise.resolve(cachedImg)
    }
    return new Promise((resolve, reject) => {
      const img = new Image()
      img.crossOrigin = 'anonymous'
      img.onload = () => { cachedImg = img; cachedUrl = url; resolve(img) }
      img.onerror = reject
      img.src = url
    })
  }

  function schedule() {
    if (!sourceImageUrl.value) return
    if (timer != null) window.clearTimeout(timer)
    timer = window.setTimeout(() => { timer = null; void run() }, SCHEDULE_DELAY_MS)
  }

  async function run() {
    const url = sourceImageUrl.value
    const r = rows.value, c = cols.value
    if (!url || r < 1 || c < 1) return

    const mySeq = ++seq
    splitting.value = true
    try {
      const img = await getSourceImage(url)
      if (mySeq !== seq) return
      const b = Math.max(0, Math.round(border.value))
      const o = outerBorder.value ? 1 : 0
      const cellW = Math.floor((img.naturalWidth  - (c - 1 + 2 * o) * b) / c)
      const cellH = Math.floor((img.naturalHeight - (r - 1 + 2 * o) * b) / r)
      if (cellW < 1 || cellH < 1) return

      const items: { index: string; label: string; image_url: string }[] = []
      let n = 0
      const nodeId = String(node?.id ?? 'unknown')
      for (let row = 0; row < r; row++) {
        for (let col = 0; col < c; col++) {
          if (mySeq !== seq) return
          n++
          const canvas = document.createElement('canvas')
          canvas.width = cellW
          canvas.height = cellH
          const ctx = canvas.getContext('2d')
          if (!ctx) throw new Error('2d context unavailable')
          ctx.drawImage(img, o * b + col * (cellW + b), o * b + row * (cellH + b), cellW, cellH, 0, 0, cellW, cellH)

          const imageUrl = await uploadCanvas(canvas, {
            subfolder: 'comfytv/gridsplit',
            filename: `comfytv-grid-${nodeId}-${Date.now()}-${n}.png`,
          })
          if (mySeq !== seq) return

          items.push({
            index: String(n),
            label: `R${row + 1}C${col + 1}`,
            image_url: imageUrl,
          })
        }
      }
      if (mySeq !== seq) return
      store.applyExecutedPayload(state, { output: [JSON.stringify({ images: items })] })
    } catch (e) {
      console.error('[ComfyTV/gridsplit] split failed', e)
    } finally {
      if (mySeq === seq) splitting.value = false
    }
  }

  watch([rows, cols, border, outerBorder], ([r, c, b, o]) => {
    writeWidget(node, 'rows', r)
    writeWidget(node, 'cols', c)
    writeWidget(node, 'border', b)
    writeWidget(node, 'outer_border', o)
    schedule()
  })
  watch(sourceImageUrl, () => schedule(), { immediate: true })

  return {
    sourceImageUrl,
    rows, cols, setGrid,
    border, setBorder,
    outerBorder, setOuterBorder,
    splitting,
  }
}
